import React from 'react'

function Task(props) {

    const { id, libelle, complete } = props
    // console.log(props)
    return (
        <>
            {!complete && (
                <div className='task-item'>
                    <span className={`task-name ${complete ? 'complete' : ''}`}>
                        {props.libelle}
                    </span>
                    <buton className='task-action-btn complete-btn' onClick={complete ? handleUndo : handleComplete}>
                        {complete ? 'Undo' : 'Complete'}
                    </buton>
                    <buton className='task-action-btn delete-btn' onClick={handleDelete}>
                        delete
                    </buton>
                </div>
            )
            }
        </>
    )
}

export default Task
